    /// Tracks `workspace_settings_updated`.
    public func workspaceSettingsUpdated(
      workspaceId: String,
      setting: String,
      extras: [String: Any]? = nil,
      options: TrackOptions? = nil
    ) {
      facade.trackTyped(
        WellKnownEvents.workspaceSettingsUpdated,
        [workspaceId, setting],
        extras: extras,
        options: options
      )
    }
  }
}
